\documentclass[tikz,border=10pt]{standalone}
\definecolor{brickred}{RGB}{214, 106, 106}
\definecolor{darkcenter}{RGB}{168, 62, 62}
\begin{document}
\begin{tikzpicture}
% fixed canvas: keeps the crop identical to the other blood type images,
% so the cell is drawn at exactly the same size in all four
\useasboundingbox (0,0) circle (3.6cm);
% outer ring: lighter brick red (thicker rim of the cell)
\fill[brickred] (0,0) circle (3cm);
% inner disc: darker red-brown (central depression)
\fill[darkcenter] (0,0) circle (1.5cm);
\end{tikzpicture}
\end{document}
